#!/usr/bin/env bash
# Wrapper for `cargo check` / `cargo build` that points cargo at a local
# SSD target directory to avoid macOS NFS client resource-fork pollution.
#
# Why: when the repo lives on an NFS mount (e.g. /Volumes/CC via Synology),
# the macOS NFS client writes a `._<filename>` resource-fork sibling for
# every file tauri 2.x build.rs creates in `target/**/autogenerated/`.
# tauri build.rs then reads that directory back and panics on the non-UTF-8
# `._default.toml`. Compiling into a local target directory (APFS) bypasses
# the NFS client entirely. This is the same root cause as the older "macOS
# SMB resource-fork" issue, and the same fix applies.
#
# Usage: scripts/cargo-check-clean.sh check
#        scripts/cargo-check-clean.sh build
#        scripts/cargo-check-clean.sh tauri dev
#        scripts/cargo-check-clean.sh test office_gateway
#
# Override the target dir with CARGO_TARGET_DIR before calling this script.

set -euo pipefail

# Locate repo root (works whether invoked from anywhere)
ROOT="$(git rev-parse --show-toplevel 2>/dev/null || pwd)"

# Default CARGO_TARGET_DIR to a local SSD path (override by exporting before invoke)
export CARGO_TARGET_DIR="${CARGO_TARGET_DIR:-$HOME/ccswitch-target}"
mkdir -p "$CARGO_TARGET_DIR"

# Tell macOS tools (cp, ditto, tar, etc.) to skip resource forks where possible.
# NOTE: This does NOT help with std::fs::write (Rust bypasses the kernel
# copyfile call) — only the CARGO_TARGET_DIR relocation above actually fixes
# the NFS-induced ._*.toml pollution.
export COPYFILE_DISABLE=1

# Start a background watcher that sweeps any leftover ._*.toml files in the
# (now local) target dir during the cargo invocation. Belt-and-suspenders;
# not strictly required once CARGO_TARGET_DIR is local.
WATCHER_OUT="$(mktemp -t cargo-check-clean.XXXXXX)"
(
  while true; do
    find "$CARGO_TARGET_DIR" -name "._*.toml" -type f -delete 2>/dev/null || true
    sleep 0.1
  done
) > "$WATCHER_OUT" 2>&1 &
WATCHER_PID=$!

cleanup() {
  kill "$WATCHER_PID" 2>/dev/null || true
  wait "$WATCHER_PID" 2>/dev/null || true
  rm -f "$WATCHER_OUT"
}
trap cleanup EXIT INT TERM

echo "[cargo-check-clean] CARGO_TARGET_DIR=$CARGO_TARGET_DIR; running: cargo $*"

# Delegate to the real cargo
exec cargo "$@"
